begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,auth;
select no_plan();
-- Independent Python hashlib/ASCII golden values; numeric bytes are synthetic.
-- Rows are bound to the immutable artifact; no identity registry fixtures.
create function pg_temp.v2_ref() returns jsonb language sql immutable as $body$ select $json${"artifactId":"87920000-0000-4000-8000-000000000001","manifestByteSize":964,"manifestSha256":"fdbe20a86ec364c4eb2beab0ae497960181b712d6f3b6f53be26cd9f64d2d9dc","schemaVersion":"tiangong.query-artifact.v2"}$json$::jsonb $body$;
create function pg_temp.v2_rows() returns jsonb language sql immutable as $body$ select $json$[{"canonicalContentHash":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","contentHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","ordinal":0,"relationKind":"direct","sources":[{"uuid":"87920000-0000-4000-8000-000000000030","version":"01.00.000"}],"uuid":"87920000-0000-4000-8000-000000000010","version":"01.00.000"},{"canonicalContentHash":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","contentHash":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","ordinal":1,"relationKind":"derived","sources":[{"uuid":"87920000-0000-4000-8000-000000000030","version":"01.00.000"},{"uuid":"87920000-0000-4000-8000-000000000031","version":"01.00.000"}],"uuid":"87920000-0000-4000-8000-000000000011","version":"01.00.000"}]$json$::jsonb $body$;
create function pg_temp.v2_receipt() returns jsonb language sql immutable as $body$ select $json${"artifact":{"artifactId":"87920000-0000-4000-8000-000000000001","manifestByteSize":964,"manifestSha256":"fdbe20a86ec364c4eb2beab0ae497960181b712d6f3b6f53be26cd9f64d2d9dc","schemaVersion":"tiangong.query-artifact.v2"},"files":[{"byteSize":100,"name":"impacts.json.gz","sha256":"c4bb33fd06c893f11887ac73645bfbce20d259882c8d5e665ec7b89e9cf72a87"},{"byteSize":100,"name":"inventory-items.json.gz","sha256":"6fba6f118b0d3eb79708d8c4659a6329cb74897e026d8f698f7c6a4298d29c89"},{"byteSize":100,"name":"lci.h5","sha256":"d0841df362f60359c2c835d97561f5896d47f8e73653d8739e43dab40f4c4974"},{"byteSize":100,"name":"lcia.h5","sha256":"52f50daca336baa412eb1b56a2aa5fc26940281c3c8c7a07518dfcbdd62f8ba1"},{"byteSize":964,"name":"manifest.json","sha256":"fdbe20a86ec364c4eb2beab0ae497960181b712d6f3b6f53be26cd9f64d2d9dc"},{"byteSize":100,"name":"results.json.gz","sha256":"06d6204d6cf8fd380099ae9c23690151fed0f2583fb507501f691ba3c1a279cb"}],"inputHash":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff","readbackId":"87920000-0000-4000-8000-000000000040","rowBindingsSha256":"541f91dc98b8b1784e548aa311753ea61de66a6007ebcee2e3fa4a8b62503737","schemaVersion":"tiangong.final-result-query-readback.v1","targetHash":"dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd","verification":"full-get-sha256-and-axis","verifiedAt":"DYNAMIC"}$json$::jsonb $body$;
create function pg_temp.v2_manifest() returns text language sql immutable as $body$ select $json${"artifactId":"87920000-0000-4000-8000-000000000001","files":[{"byteSize":100,"name":"impacts.json.gz","plainByteSize":500,"sha256":"c4bb33fd06c893f11887ac73645bfbce20d259882c8d5e665ec7b89e9cf72a87"},{"byteSize":100,"name":"inventory-items.json.gz","plainByteSize":500,"sha256":"6fba6f118b0d3eb79708d8c4659a6329cb74897e026d8f698f7c6a4298d29c89"},{"byteSize":100,"name":"lci.h5","sha256":"d0841df362f60359c2c835d97561f5896d47f8e73653d8739e43dab40f4c4974"},{"byteSize":100,"name":"lcia.h5","sha256":"52f50daca336baa412eb1b56a2aa5fc26940281c3c8c7a07518dfcbdd62f8ba1"},{"byteSize":100,"name":"results.json.gz","plainByteSize":500,"sha256":"06d6204d6cf8fd380099ae9c23690151fed0f2583fb507501f691ba3c1a279cb"}],"impactCount":1,"inventoryCount":3,"lciNonzeroCount":2,"resultCount":2,"schemaVersion":"tiangong.query-artifact.v2","source":{"inputHash":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff","schemaVersion":"tiangong.final-result-projection.v1"}}$json$::text $body$;
grant execute on function pg_temp.v2_ref(),pg_temp.v2_rows(),pg_temp.v2_receipt(),pg_temp.v2_manifest() to service_role;
create function pg_temp.stage_changed_manifest(p_changes jsonb) returns jsonb language plpgsql as $$
declare v_text text:=(pg_temp.v2_manifest()::jsonb || p_changes)::text; v_ref jsonb:=pg_temp.v2_ref();
begin
  v_ref:=jsonb_set(jsonb_set(v_ref,'{manifestByteSize}',to_jsonb(octet_length(v_text))),'{manifestSha256}',
    to_jsonb(encode(extensions.digest(convert_to(v_text,'UTF8'),'sha256'),'hex')));
  return api.svc_result_query_stage_v2(v_ref,v_text,pg_temp.v2_rows());
end;
$$;
grant execute on function pg_temp.stage_changed_manifest(jsonb) to service_role;
create temporary table seal_receipt as select jsonb_set(pg_temp.v2_receipt(),'{verifiedAt}',to_jsonb(clock_timestamp())) as value;
grant select on seal_receipt to service_role;
create temporary table compressed_rows as select jsonb_set(pg_temp.v2_rows(),'{0,sources,0,uuid}',to_jsonb(repeat('0',1048577))) value;
grant select on compressed_rows to service_role;
select ok((select pg_column_size(value)<1048576 and octet_length(value::text)>1048576 from compressed_rows),'compressed fixture exceeds the logical request budget');
select ok(not has_function_privilege('authenticated','api.svc_result_query_stage_v2(jsonb,text,jsonb)','execute') and not has_function_privilege('anon','api.svc_result_query_seal_v2(uuid,jsonb)','execute'),'v2 writes are service-only');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('final_result_query_artifacts','final_result_query_rows','final_result_query_sources','final_result_query_seals') and c.relrowsecurity),4::bigint,'all v2 relations retain RLS');
select ok(not has_table_privilege('service_role','private.final_result_query_rows','select,insert,update,delete'),'raw service access remains closed');
set local role service_role;
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),(select value from compressed_rows))$q$,'22023','Invalid final Result query stage input','TOAST compression cannot bypass the request byte limit');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"inventoryCount":-1}')$q$,'22023','Invalid final Result query integer','negative dimensions are rejected');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"resultCount":2000001}')$q$,'22023','Final Result query integer exceeds budget','result dimension is bounded');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"impactCount":4097}')$q$,'22023','Final Result query integer exceeds budget','method dimension is bounded');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"lciNonzeroCount":7}')$q$,'22023','Invalid final Result query dimensions','sparse count cannot exceed the complete matrix');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"files":[]}')$q$,'22023','Invalid final Result query file set','all files must be declared');
select throws_ok($q$select pg_temp.stage_changed_manifest(jsonb_build_object('files',jsonb_set(pg_temp.v2_manifest()::jsonb->'files','{0,name}','"../impacts.json.gz"')))$q$,'22023','Invalid final Result query file','file names cannot introduce paths');
select throws_ok($q$select pg_temp.stage_changed_manifest(jsonb_build_object('files',jsonb_set(pg_temp.v2_manifest()::jsonb->'files','{0,plainByteSize}','134217729')))$q$,'22023','Final Result query integer exceeds budget','decompressed metadata is bounded');
select throws_ok($q$select pg_temp.stage_changed_manifest('{"source":{"schemaVersion":"tiangong.calculation-bundle.v2","inputHash":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"}}')$q$,'22023','Invalid final Result query manifest','final input cannot be replaced with a calculation Bundle');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest()||' ',pg_temp.v2_rows())$q$,'22023','Final Result query manifest bytes mismatch','raw byte changes cannot reuse a manifest identity');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),'[]')$q$,'22023','Final Result query manifest bytes mismatch','empty batches cannot create staging records');
select throws_ok($q$select api.svc_result_query_stage_v2(jsonb_set(pg_temp.v2_ref(),'{schemaVersion}','"tiangong.query-artifact.v1"'),pg_temp.v2_manifest(),pg_temp.v2_rows())$q$,'22023','Final Result query manifest bytes mismatch','v1 references are not reinterpreted');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{0,canonicalContentHash}','"87920000-0000-4000-8000-000000000099"'))$q$,'22023','Invalid final Result query row','canonical content hash shape is checked');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{0,contentHash}',to_jsonb(repeat('e',63))))$q$,'22023','Invalid final Result query row','content digest shape is checked');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{0,ordinal}','2'))$q$,'22023','Final Result query integer exceeds budget','out-of-range row cannot fill an incomplete axis');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{0,ordinal}','0.5'))$q$,'22023','Invalid final Result query integer','fractional ordinals are rejected');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{1,relationKind}','"direct"'))$q$,'22023','Invalid final Result query lineage','multi-source derived Result cannot masquerade as direct');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{1,sources}',jsonb_build_array(pg_temp.v2_rows()#>'{1,sources,0}',pg_temp.v2_rows()#>'{1,sources,0}')))$q$,'22023','Duplicate final Result query source identity','duplicate lineage source is rejected');
select is(api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_build_array(pg_temp.v2_rows()->0))#>>'{data,registeredResultCount}','1','first bounded batch is stored');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,(select value from seal_receipt))$q$,'22023','Final Result query axis is incomplete','incomplete artifact cannot seal');
select is(api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_build_array(pg_temp.v2_rows()->1))#>>'{data,registeredResultCount}','2','second batch completes contiguous axis');
select is(api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),pg_temp.v2_rows())#>>'{data,registeredResultCount}','2','exact batch retry is idempotent');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),jsonb_set(pg_temp.v2_rows(),'{0,relationKind}','"derived"'))$q$,'23505','Final Result query row identity conflict','same axis identity cannot change relation kind');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,jsonb_set((select value from seal_receipt),'{rowBindingsSha256}',to_jsonb(repeat('a',64))))$q$,'22023','Final Result query axis readback mismatch','readback must bind actual registered row mapping');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,jsonb_set((select value from seal_receipt),'{files}','[]'))$q$,'22023','Final Result query file readback mismatch','upload/ETag-only proof cannot seal');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,jsonb_set((select value from seal_receipt),'{verifiedAt}',to_jsonb(clock_timestamp()-interval '1 hour')))$q$,'22023','Final Result query readback is not fresh','stale first readback is rejected');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,jsonb_set((select value from seal_receipt),'{verifiedAt}','"infinity"'))$q$,'22023','Final Result query readback is not fresh','infinite timestamp does not qualify');
select is(api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,(select value from seal_receipt))#>>'{data,sealed}','true','complete raw files and independently hashed row axis seal');
select is(api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,(select value from seal_receipt))#>>'{data,sealed}','true','lost-ack retry reuses same immutable seal');
select is(api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,(select value from seal_receipt))#>>'{data,publicationAuthorized}','false','seal never grants publication authority');
select throws_ok($q$select api.svc_result_query_seal_v2((pg_temp.v2_ref()->>'artifactId')::uuid,jsonb_set((select value from seal_receipt),'{readbackId}','"87920000-0000-4000-8000-000000000099"'))$q$,'23505','Final Result query seal identity conflict','seal history cannot be replaced');
select is(api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),pg_temp.v2_rows())#>>'{data,registeredResultCount}','2','same stage retry remains safe after seal');
reset role;
select is((select row_hash from private.final_result_query_rows where artifact_id='87920000-0000-4000-8000-000000000001' and row_ordinal=0),'22fb005f7abc293fa09035308cf4c0caadfd7e0d62bda4f2e00b97164b7b58f8','row 0 hash matches independent ASCII golden');
select is((select row_hash from private.final_result_query_rows where artifact_id='87920000-0000-4000-8000-000000000001' and row_ordinal=1),'bfb6a3c35422aa0270edbb0a4b946d064f4bf5c4fbdb815daf5c0cc15f8f07b8','row 1 hash matches independent ASCII golden');
select is((select count(*) from private.final_result_query_sources where source_id='87920000-0000-4000-8000-000000000030'),2::bigint,'one source can have a direct Result and a separate derived Result');
select is((select count(*) from private.final_result_query_rows where relation_kind='direct' and artifact_id=(pg_temp.v2_ref()->>'artifactId')::uuid),1::bigint,'derived result does not substitute for the direct result');
select throws_ok($q$update private.final_result_query_rows set relation_kind='derived' where artifact_id=(pg_temp.v2_ref()->>'artifactId')::uuid$q$,'55000','Result query evidence is immutable','row mappings cannot be edited');
select throws_ok($q$delete from private.final_result_query_seals where artifact_id=(pg_temp.v2_ref()->>'artifactId')::uuid$q$,'55000','Result query evidence is immutable','seal evidence cannot be deleted');
select is((select count(*) from public.processes where id in ('87920000-0000-4000-8000-000000000010','87920000-0000-4000-8000-000000000011')),0::bigint,'v2 does not insert state-120 Process rows');
select is((select count(*) from private.result_query_artifacts where id=(pg_temp.v2_ref()->>'artifactId')::uuid),0::bigint,'v1 package registry is untouched');
-- Duplicate JSON keys must not hash as one body and decode as another reader's
-- interpretation, even when the caller supplies the correct raw-byte digest.
do $$ declare v_text text:=replace(pg_temp.v2_manifest(),'"resultCount":2','"resultCount":1,"resultCount":2'); v_ref jsonb:=pg_temp.v2_ref();
begin
  v_ref:=jsonb_set(jsonb_set(v_ref,'{manifestByteSize}',to_jsonb(octet_length(v_text))),'{manifestSha256}',to_jsonb(encode(extensions.digest(convert_to(v_text,'UTF8'),'sha256'),'hex')));
  create temporary table duplicate_manifest as select v_ref ref,v_text body;
end $$;
select throws_ok($q$select api.svc_result_query_stage_v2((select ref from duplicate_manifest),(select body from duplicate_manifest),pg_temp.v2_rows())$q$,'22023','Invalid final Result query manifest','duplicate manifest keys are rejected before decoding');
select throws_ok($q$select api.svc_result_query_stage_v2(pg_temp.v2_ref(),pg_temp.v2_manifest(),(select jsonb_agg(pg_temp.v2_rows()->0) from generate_series(1,501)))$q$,'22023','Final Result query manifest bytes mismatch','a single call cannot exceed 500 row records');
select * from finish();
rollback;
